import { Plugin, PluginContext, PluginConfig } from '@lemur-engine/core';
import { {{name}}Service } from './services/{{name}}Service';
import { {{name}}Controller } from './controllers/{{name}}Controller';
import { {{name}}Repository } from './repositories/{{name}}Repository';
import { {{name}}Config } from './types';

export default class {{name}}Plugin implements Plugin {
  private service: {{name}}Service;
  private config: {{name}}Config;

  constructor(private context: PluginContext) {}

  async initialize(): Promise<void> {
    // Cargar configuración
    this.config = this.context.config.get('{{name}}') as {{name}}Config;

    // Registrar dependencias
    this.context.container.register('{{name}}Repository', {{name}}Repository);
    this.context.container.register('{{name}}Service', {{name}}Service);
    this.context.container.register('{{name}}Controller', {{name}}Controller);

    // Inicializar servicios
    this.service = this.context.container.resolve('{{name}}Service');

    this.context.logger.info('{{name}} plugin inicializado');
  }

  async start(): Promise<void> {
    // Registrar rutas y eventos
    const controller = this.context.container.resolve('{{name}}Controller');
    controller.registerRoutes();

    // Suscribirse a eventos
    this.context.events.on('system.ready', () => {
      this.context.logger.info('Sistema listo, iniciando {{name}} plugin');
    });

    // Iniciar servicios
    await this.service.start();

    this.context.logger.info('{{name}} plugin iniciado');
  }

  async stop(): Promise<void> {
    // Detener servicios
    await this.service.stop();

    // Limpiar recursos
    this.context.events.removeAllListeners();

    this.context.logger.info('{{name}} plugin detenido');
  }
}

