import { Injectable } from '@lemur-engine/core';
import { {{name}}Data } from '../types';

@Injectable()
export class {{name}}Repository {
  private data: Map<string, {{name}}Data> = new Map();

  async findAll(): Promise<{{name}}Data[]> {
    return Array.from(this.data.values());
  }

  async findById(id: string): Promise<{{name}}Data | undefined> {
    return this.data.get(id);
  }

  async create(data: {{name}}Data): Promise<{{name}}Data> {
    this.data.set(data.id, data);
    return data;
  }

  async update(id: string, data: Partial<{{name}}Data>): Promise<{{name}}Data> {
    const existing = this.data.get(id);
    if (!existing) throw new Error('Registro no encontrado');

    const updated = { ...existing, ...data };
    this.data.set(id, updated);
    return updated;
  }

  async delete(id: string): Promise<void> {
    this.data.delete(id);
  }
}

