  // Define los datos del plugin
  [key: string]: unknown;
}

import { createMockPluginContext } from '@lemur-engine/testing';
import {{name}}Plugin from '../src';
import { {{name}}Service } from '../src/services/{{name}}Service';

describe('{{name}}Plugin', () => {
  let plugin: {{name}}Plugin;
  let context: any;

  beforeEach(() => {
    context = createMockPluginContext();
    plugin = new {{name}}Plugin(context);
  });

  it('debería inicializarse correctamente', async () => {
    await plugin.initialize();
    expect(context.logger.info).toHaveBeenCalledWith('{{name}} plugin inicializado');
  });

  it('debería registrar las dependencias correctamente', async () => {
    await plugin.initialize();
    const service = context.container.resolve('{{name}}Service');
    expect(service).toBeInstanceOf({{name}}Service);
  });

  it('debería iniciar y detener servicios correctamente', async () => {
    await plugin.initialize();
    await plugin.start();
    expect(context.logger.info).toHaveBeenCalledWith('{{name}} plugin iniciado');

    await plugin.stop();
    expect(context.logger.info).toHaveBeenCalledWith('{{name}} plugin detenido');
  });
});

